"""Deterministic descriptive analysis; no inference, target acquisition or fitting."""
import json,statistics
from collect_smollm_v47 import ROOT,read,write,sha
OUT=ROOT/'results/v136_feedback'
def gain(ref,value,direction):return (ref-value)/ref if direction=='-' else (value-ref)/ref
def contrast(values):return {'mean':statistics.mean(values),'wins':sum(v>1e-12 for v in values),'ties':sum(abs(v)<=1e-12 for v in values),'losses':sum(v< -1e-12 for v in values)}
def main():
 jobs=read(ROOT/'artifacts/study_v136/jobs.json');summary=read(OUT/'summary.json');assert summary['complete'];rows=[]
 for j in jobs:
  spec=read(ROOT/f"artifacts/study_v136/candidates/{j['system_group']}.json")['spec'];direction=spec['direction'];best=lambda s:(min if direction=='-' else max)(y[0] for y in s['labels'])
  r={'key':j['key'],'system_group':j['system_group'],'seed':j['seed'],'direction':direction,'prefix':best(read(ROOT/j['prefix'])['state'])}
  for mode in ['feedback','masked']:r[mode]=best(read(OUT/'arms'/f"{j['key']}_{mode}.json")['state'])
  for mode in ['historical_batch','historical_sequential']:r[mode]=best(read(ROOT/j[mode])['state'])
  rows.append(r)
 responses=[json.loads(x) for x in (OUT/'responses.jsonl').read_text().splitlines()];selections=[read(p) for p in sorted((OUT/'selections').glob('*.json'))];ledger=read(OUT/'ledger.json')
 groups={}
 for group in sorted({r['system_group'] for r in rows}):
  subset=[r for r in rows if r['system_group']==group];g={}
  for mode in ['feedback','masked']:
   for ref in ['prefix','historical_sequential','historical_batch']:
    g[f'{mode}_vs_{ref}']=contrast([gain(r[ref],r[mode],r['direction']) for r in subset])
  g['feedback_vs_masked']=contrast([gain(r['masked'],r['feedback'],r['direction']) for r in subset]);groups[group]=g
 usage={field:{'observed_sum':sum(r['response'][field] for r in responses if type(r['response'].get(field)) is int),'missing_intended_responses':100-sum(type(r['response'].get(field)) is int for r in responses)} for field in ['tokens_predicted','tokens_evaluated']}
 costs={**ledger,'usage':usage,'new_recorded_acquisitions':summary['new_acquisitions'],'total_collection_seconds':summary['total_seconds'],'evaluation_seconds':sum(read(p)['evaluation_seconds'] for p in (OUT/'rounds').glob('*.json')),'per_arm':{f"{j['key']}_{m}":{'observed_request_seconds':sum(r['wall_seconds'] for r in responses if r['identity'].startswith(f"{j['key']}_{m}_")),'requests_returned':sum(r['identity'].startswith(f"{j['key']}_{m}_") for r in responses)} for j in jobs for m in ['feedback','masked']}}
 diagnostics={'valid_rounds':sum(not s['fallback'] for s in selections),'fallback_rounds':sum(s['fallback'] for s in selections),'projected_proposals':sum(d['hamming_distance']>0 for s in selections for d in s['diagnostics']),'repeated_within_round':sum(d['repeated_proposal'] for s in selections for d in s['diagnostics']),'proposals_matching_acquired':sum(d['matches_acquired'] for s in selections for d in s['diagnostics']),'proposals_with_diagnostics':sum(len(s['diagnostics']) for s in selections)}
 initial={r['identity']:r['response']['content'] for r in responses if r['identity'].endswith('_0')}
 diagnostics['same_round_zero_output_cases']=sum(initial.get(f"{j['key']}_feedback_0") is not None and initial.get(f"{j['key']}_feedback_0")==initial.get(f"{j['key']}_masked_0") for j in jobs)
 rawmap={r['identity']:r for r in responses};trace=[]
 for j in jobs:
  for r in range(1,5):
   a=f"{j['key']}_feedback_{r}";b=f"{j['key']}_masked_{r}"
   trace.append({'key':j['key'],'system_group':j['system_group'],'round':r,'both_responses':a in rawmap and b in rawmap,'same_output':a in rawmap and b in rawmap and rawmap[a]['response']['content']==rawmap[b]['response']['content'],'same_selected_rows':read(OUT/'selections'/f'{a}.json')['rows']==read(OUT/'selections'/f'{b}.json')['rows']})
 write(OUT/'followup_trace.json',{'scope':'Post-outcome exploratory trace audit, no new acquisitions or requests, not another predeclared hypothesis test','pairs':trace})
 result={'scope':'Two exposed groups; matched five-call feedback ablation; descriptive, not held-out generalization','rows':rows,'groups':groups,'diagnostics':diagnostics,'actual_collection_cost':costs,'estimated_deployment':{'objective_evaluations':20,'prefix':10,'model_requests_per_escalation':5,'allocated_output_tokens':1280,'note':'One chosen arm; measured request time excludes shared server startup and historical prefix/controller costs. No dollars, energy or native execution savings inferred.'}}
 write(OUT/'comparison.json',result)
 text=['# V136: matched-call sequential feedback diagnostic','','This is a prospective diagnostic on two previously exposed recorded software families, LLVM (10 features) and SAC (59), chosen by feature-count extremes among the six original families. Five fixed seeds each. Both arms start from the same B10 prefix, make five real calls proposing two settings each, and finish at B20. Feedback receives its own new measured outcomes; masked receives newly tried settings with outcomes withheld. No router was fitted. Ten paired seeds are only two independent software groups.','','Primary comparison: does feedback improve the final incumbent at the same model-call and objective budget? Positive values favor feedback.','','| Family | Feedback vs masked | Wins/ties/losses | Feedback vs sequential3NN | Masked vs sequential3NN |','|---|---:|---:|---:|---:|']
 for group,g in groups.items():
  c=g['feedback_vs_masked'];text.append(f"| {group} | {100*c['mean']:.4f}% | {c['wins']}/{c['ties']}/{c['losses']} | {100*g['feedback_vs_historical_sequential']['mean']:.4f}% | {100*g['masked_vs_historical_sequential']['mean']:.4f}% |")
 text+=['','| Family / seed | Prefix incumbent | Feedback | Masked | Historical sequential | Historical one-shot batch |','|---|---:|---:|---:|---:|---:|']
 for r in sorted(rows,key=lambda r:(r['system_group'],r['seed'])):text.append(f"| {r['system_group']} / {r['seed']} | {r['prefix']:.9g} | {r['feedback']:.9g} | {r['masked']:.9g} | {r['historical_sequential']:.9g} | {r['historical_batch']:.9g} |")
 text+=['','LLVM minimizes the recorded compiler optimization time; SAC minimizes recorded n-body execution time, in their original source units. Cross-family raw values must not be pooled. Historical classical and one-shot controls reuse verified identical prefixes. Historical one-shot prompts/grammar/output caps differ (LLVM V127; valid SAC repair V135), so comparison with them does not isolate feedback alone. Old failed SAC responses are not replaced.', '', 'Additional descriptive contrasts:','', '| Family / arm | Gain vs prefix | Prefix improvements /5 | Gain vs historical one-shot |','|---|---:|---:|---:|']
 for group,g in groups.items():
  for mode in ['feedback','masked']:text.append(f"| {group} / {mode} | {100*g[f'{mode}_vs_prefix']['mean']:.4f}% | {g[f'{mode}_vs_prefix']['wins']} | {100*g[f'{mode}_vs_historical_batch']['mean']:.4f}% |")
 text+=['',f"Reliability: {diagnostics['valid_rounds']}/100 valid round responses; {diagnostics['fallback_rounds']} fallback rounds, zero retries. Of {diagnostics['proposals_with_diagnostics']} valid proposals, {diagnostics['projected_proposals']} required nonzero feature-distance projection, {diagnostics['repeated_within_round']} repeated the other proposal within their round, and {diagnostics['proposals_matching_acquired']} exactly matched an already acquired setting before projection. All selected rows remained unique within their B20 arm. Identical round-zero prompts and sampling seeds yielded identical text in {diagnostics['same_round_zero_output_cases']}/10 cases.",'',f"A post-outcome exploratory trace audit (followup_trace.json) finds {sum(t['both_responses'] and not t['same_output'] for t in trace)}/40 follow-up pairs with different raw outputs and {sum(not t['same_selected_rows'] for t in trace)}/40 with different selected rows. Tied final incumbents therefore do not mean the model ignored the changed prompt or followed identical search paths. Changed text alone does not establish beneficial use of feedback.",'',f"Actual collection: {ledger['generation_requests']} real local requests, {usage['tokens_predicted']['observed_sum']} observed generated and {usage['tokens_evaluated']['observed_sum']} observed prefill tokens; missing intended usage receipts {usage['tokens_predicted']['missing_intended_responses']}/{usage['tokens_evaluated']['missing_intended_responses']}. Allocated output tokens {ledger['allocated_output_tokens']}; {summary['new_acquisitions']} newly charged recorded acquisitions. Model lifecycle {ledger['stage_seconds']:.3f}s, overall collection {summary['total_seconds']:.3f}s, recorded evaluation {costs['evaluation_seconds']:.6f}s; peak sampled server RSS {ledger['peak_server_rss_bytes']:,}bytes. No new native workload, download, retry, paid/cloud call or spending.",'','Deployment accounting: one escalation requires five requests and ten additional evaluations after B10 (B20 total), with1280 allocated output tokens. Per-arm measured request times are in comparison.json and exclude cold start and historical prefix collection. Actual research collection includes both arms and all100 requests; historical controls retain their original costs. No monetary, energy or actual software runtime saving is inferred from recorded-table access time.','','Limits: two exposed groups cannot validate a learned router or establish journal readiness. The intervention supplies numeric feedback in symbolic configuration space; it is not an exact SNAP2/LLAMBO reproduction. Five rounds of two proposals are not fully sequential one-proposal feedback. Hamming projection can dominate model suggestions. These are fixed recorded observations, not fresh native correctness or noise tests. Shared hardware and a single quantized8B model limit transfer claims. No tuning or further batch is triggered by whether this result is favorable.','','Provenance: reports/protocol_v136.md and protocol_v136.freeze.json; artifacts/study_v136/jobs.json and candidates; results/v136_feedback decisions, preflight, generation_starts.jsonl, responses.jsonl, selections, acquisitions.jsonl, rounds, arms, runtime/ledger/summary. Every selection precedes its charged labels. Independent standard-library replay reconstructs prompts, masking, sampling, projection, raw source rows and contrasts. Synthetic tests are separate. Prior V135 config had a stale split label; protocol/report were already explicit exposed development; see prior_metadata_erratum.json.','','Safe reproduction: `.venv/bin/python scripts/verify_feedback_v136.py` then `.venv/bin/python scripts/analyze_feedback_v136.py`. These commands make no model requests and acquire no new outcomes.']
 (ROOT/'reports/feedback_v136.md').write_text('\n'.join(text)+'\n')
 import matplotlib;matplotlib.use('Agg');matplotlib.rcParams['svg.hashsalt']='v136-feedback'
 import matplotlib.pyplot as plt
 fig,axes=plt.subplots(1,2,figsize=(10,4),layout='constrained')
 for ax,group in zip(axes,sorted(groups)):
  rs=sorted([r for r in rows if r['system_group']==group],key=lambda r:r['seed'])
  for k,(mode,label,color) in enumerate([('feedback','Feedback (5 calls)','#2166ac'),('masked','Masked (5 calls)','#b2182b'),('historical_batch','Historical batch (1 call)','#999999')]):
   ax.bar([i+(k-1)*.24 for i in range(5)],[100*gain(r['historical_sequential'],r[mode],r['direction']) for r in rs],.23,label=label,color=color)
  ax.axhline(0,color='black',linewidth=.7);ax.set_xticks(range(5),[r['seed'] for r in rs]);ax.set_xlabel('Fixed seed (within one exposed system)');ax.set_ylabel('Gain vs historical sequential3NN (%)');ax.set_title(group.upper());ax.legend(fontsize=7)
 fig.suptitle('B10 → B20: matched-call feedback diagnostic (two exposed systems)',fontsize=11)
 fig.savefig(OUT/'comparison.png',dpi=170);fig.savefig(OUT/'comparison.svg',metadata={'Date':None});plt.close(fig)
 print(json.dumps({'groups':groups,'diagnostics':diagnostics,'cost':costs},indent=2))
if __name__=='__main__':main()
